mapper.select:
SELECT id, name, region, address, contact_email AS contactEmail, contact_phone AS contactPhone, type, business_number AS businessNumber, external_source AS externalSource, external_key AS externalKey, created_at AS createdAt, updated_at AS updatedAt FROM companies
AND region = #{region}
AND type = #{type}
ORDER BY id ASC

